@@ -3,6 +3,7 @@
 ## Unreleased

 - Faster tag lookup.
+- Fix days left and expiry to use UTC calendar dates: an item is good through the end of its expiry date.

 ## 1.4.2 - 2026-09-30

diff --git a/src/expiry.js b/src/expiry.js
index 0a7b267..9b16b01 100644
--- a/src/expiry.js
+++ b/src/expiry.js
@@ -2,9 +2,11 @@ import { log } from "./log.js";

 const DAY = 86400000;

-/** Whole days until the item expires (negative once expired). */
+/** UTC calendar days from the UTC date of `now` to the expiry date (negative once expired). */
 export function daysLeft(item, now = Date.now()) {
-  return Math.floor((Date.parse(item.expires) - now) / DAY);
+  const today = Math.floor(new Date(now).getTime() / DAY);
+  const expires = Math.floor(Date.parse(item.expires) / DAY);
+  return expires - today;
 }

 /** True once the item has expired; logs a warning. */
@@ -14,5 +16,5 @@ export function isExpired(item, now = Date.now()) {
     log.warn("item expired", { id: item.id, days: left });
     return true;
   }
-  return left === 0;
+  return false;
 }
